import{Un as ul,jn as qw,r as Ai,tn as hg,ur as yT}from"./chunk-CbdW2v9C.js";import"./chunk-Do2WuadP.js";import"./main-7CVFOYPV.js";import{a as k,i as j,n as T,r as _}from"./chunk-4YuWYliI.js";import{t as xe}from"./chunk-DlDZIFde.js";import{t as x}from"./chunk-DZLgnRoB.js";var c=class o{static ɵfac=function(n){return new(n||o)};static ɵcmp=yT({type:o,selectors:[[`flip-dot-display-page`]],decls:55,vars:0,consts:[[1,`divider`],[`videoId`,`s94PscZJ5EE`],[`loading`,`lazy`,`imgurId`,`NaGwOYr`],[`loading`,`lazy`,`imgurId`,`7IVaHO5`],[`loading`,`lazy`,`imgurId`,`KzctrIP`],[`loading`,`lazy`,`imgurId`,`1mmVQLA`,`aspectRatio`,`1024 / 938`],[`loading`,`lazy`,`imgurId`,`ITn7YlV`],[`loop`,``,`controls`,``,`playsInline`,``],[`src`,`https://imgur.com/6z6NkLU.mp4`,`type`,`video/mp4`],[`src`,`https://imgur.com/oezksWt.mp4`,`type`,`video/mp4`],[`videoId`,`aqdh5Y02nFw`],[`videoId`,`XeerZWMCzzU`],[`href`,`https://en.wikipedia.org/wiki/Metaballs`,`target`,`_blank`],[`videoId`,`2jxo8JOFlUs`],[`videoId`,`aWOT9Bl-654`],[`href`,`https://github.com/blakewilliams1/Flip-Dot-Project`,`target`,`_blank`]],template:function(n,g){n&1&&(Ai(0,`mat-card`)(1,`mat-card-header`)(2,`h1`),qw(3,`Flip Dot Display`),ul()(),hg(4,`div`,0),Ai(5,`mat-card-content`)(6,`p`),qw(7,` Before covid, there was a massive wall of flip dot displays tiled together in the lobby of one of the buildings at my work. It had a Microsoft Kinect sensor on it, and whenever you got close enough it would cast a silhouette of your body onto the wall that would mimic your motions. It was incredibly fun and made a really satisfying shimmering noise when in use, as the metallic disks flickered back and forth across the screens. Here's a video (not of the same wall) that gives an idea of what it was like: `),ul(),hg(8,`youtube-placeholder`,1),Ai(9,`p`),qw(10,` When everyone eventually started returning back to office, the wall had fallen into disrepair. An important 3rd party service it used on boot-up had been killed off while everyone was working from home, and the original maintainers of the wall had since left the company as well. Some folks attempted to revive it, but after several weeks of fruitless effort it was deemed not worth the time investment anymore. The panels were taken down and posted as up for grabs on the internal Makers email list. Naturally I grabbed a few and attempted to make a mini version of the original wall for myself! `),ul(),Ai(11,`p`),qw(12,` I felt the first step was to make a chassis to hold together the panels, so I bought some aluminum L-bracket from Home Depot and salvaged some aluminum T-slot rail from the recycle bins at work. Here's a progress shot of the backing frame coming together. The T-slot rails are being cut down to size and joined together `),ul(),hg(13,`img`,2),Ai(14,`p`),qw(15,` I drilled and cut aluminum L bracket down to size to hold the panels onto a larger rigid frame that was made from the T-slot rails. `),ul(),hg(16,`img`,3),Ai(17,`p`),qw(18,` Here is the final result of the frame I built for the panels! The two triangular supports on the back can be adjusted to allow it to be angled more steeply upright, and the power supplies + raspberry PI will be mounted on the rails behind the display. `),ul(),hg(19,`img`,4),Ai(20,`p`),qw(21,` Originally the display driver code was prototyped on an Arduino Uno. The mess of wires and a Raspberry Pi in the next photo was what I finally got working. I decided to go with a Raspberry Pi because there were convenient libraries for using cheap Intel RealSense depth cameras. The Raspberry Pi output is sent to a logic level shifter to convert from 3v to 5v, then finally that signal goes to a RS485 converter which the displays require. There is a lot small magnetic fields around the display to flip the discs, so they use RS485 twisted cabling to handle the large amount of electrical noise generated. `),ul(),hg(22,`img`,5),Ai(23,`p`),qw(24,` I was having issues for the longest time getting the code to work on the Raspberry Pi even though it was working fine on the Arduino. This took an EMBARRASSINGLY long time to realize and I finally had to break out the oscilloscope and decode the data being sent from each device to find the delta (next image is how it was supposed to look). I was actually sending 3 extra empty bytes in front of each intended byte... there was a single line in my code where I accidentally converted an Arduino 'byte' type to 'int' which is 4x the size. 🤦‍♂️ `),ul(),hg(25,`img`,6),Ai(26,`p`),qw(27,` Here is an example of drawing text and individual pixels [TURN SOUND ON]. I wrote a simple library for drawing text, lines, points, and raw black/white bitmaps to the screen. `),ul(),Ai(28,`video`,7),hg(29,`source`,8),ul(),Ai(30,`p`),qw(31,` This next video came from experimenting with finding the max refresh rate of the displays, which happens to be about 10 fps [TURN SOUND ON]. `),ul(),Ai(32,`video`,7),hg(33,`source`,9),ul(),Ai(34,`p`),qw(35,` I ended up getting a fourth panel! After playing with it more I felt it definitely didn't have enough pixels to use it the way I wanted. After fixing a slew of other issues regarding data corruption when passing depth cam frames between processes on the raspberry pi, I finally got that portion of it working! `),ul(),hg(36,`youtube-placeholder`,10),Ai(37,`p`),qw(38,` This was the main attraction of the flip dot wall to me; it's the tribute to the massive wall that these panels came from, and the bare minimum I'd do to feel like the project was a success, and now it is! `),ul(),Ai(39,`p`),qw(40,` After this I added on a few minigames to the project, mostly just because I could and it made the display feel more functional and fun. I started with making a quick clone of Flappy Bird, which I called "Flippy Bird" (good name idea, Chris!) `),ul(),hg(41,`youtube-placeholder`,11),Ai(42,`p`),qw(43,` Then I added a lava lamp simulation with the rendering concept of `),Ai(44,`a`,12),qw(45,`metaballs`),ul(),qw(46,` (not meatballs). `),ul(),hg(47,`youtube-placeholder`,13),Ai(48,`p`),qw(49,` Then finally I added pong because why not! `),ul(),hg(50,`youtube-placeholder`,14),Ai(51,`p`),qw(52,` I'm super happy I put in the time to finish this project, and maybe in the future I'll add some more cool features like chatGPT or Google Gemini integration if the depth camera I have has a microphone in it I can use. If you'd like to see the code I used to create this project, you can find it `),Ai(53,`a`,15),qw(54,`in this repo, on my Github`),ul()()()())},dependencies:[xe,j,_,k,T,x],styles:[`[_nghost-%COMP%]{display:block;margin:auto;padding-bottom:1px;width:fit-content}mat-card[_ngcontent-%COMP%]{margin:20px 5%;max-width:1400px}mat-card-title[_ngcontent-%COMP%]{margin-top:20px!important}h1[_ngcontent-%COMP%]{margin-top:0}img[_ngcontent-%COMP%]{width:100%}video[_ngcontent-%COMP%]{min-height:130px;width:100%}.divider[_ngcontent-%COMP%]{border-top:1px solid white;margin-bottom:1em}.youtube-player[_ngcontent-%COMP%]{aspect-ratio:16/9;display:block;margin:1em 0;width:100%}`]})};export{c as FlipDotDisplayPage};